pub fn CheckAllAllocationFailuresTuples(comptime TestFn: type) struct {
            /// `std.meta.ArgsTuple(TestFn)`
            ArgsTuple: type,
            /// `std.meta.ArgsTuple(TestFn)` without the first argument
            ExtraArgsTuple: type,
        } {
            switch (@typeInfo(@typeInfo(TestFn).@"fn".return_type.?)) {
.error_union => |info| {
if ((info.payload != void)) {
                _ = @compileError("Return type must be !void");
            }
},
else => {
_ = @compileError("Return type must be !void");
},
}
            const ArgsTuple = std.meta.ArgsTuple(TestFn);
            const fn_args_fields = std.meta.fields(ArgsTuple);
            if (((fn_args_fields.len == 0) or (fn_args_fields[0].type != std.mem.Allocator))) {
                _ = @compileError((("The provided function must have an " ++ @typeName(std.mem.Allocator)) ++ " as its first argument"));
            }
            const extra_args_tuple_info = @typeInfo(ArgsTuple);
            var extra_args_fields = (extra_args_tuple_info.@"struct".fields[1..]).*;
            _ = &extra_args_fields;
            var i: usize = 0;
            _ = &i;
            for (cp_mut_slice(&(&extra_args_fields))) |*extra_field| {
                _ = &extra_field;
                (if (@typeInfo(@TypeOf((extra_field.*))) == .@"enum" or @typeInfo(@TypeOf((extra_field.*))) == .@"union") @tagName((extra_field.*)) else (extra_field.*).name) = (if (@typeInfo(@TypeOf(fn_args_fields[@as(usize, @intCast(i))])) == .@"enum" or @typeInfo(@TypeOf(fn_args_fields[@as(usize, @intCast(i))])) == .@"union") @tagName(fn_args_fields[@as(usize, @intCast(i))]) else fn_args_fields[@as(usize, @intCast(i))].name);
                i = (i + 1);
            }
            extra_args_tuple_info.@"struct".fields = (&extra_args_fields);
            const ExtraArgsTuple = @Type(extra_args_tuple_info);
            return .{ .ArgsTuple = ArgsTuple, .ExtraArgsTuple = ExtraArgsTuple };
    }
