            var dmp: DiffMatchPatch = .{ .config = .{ .diff_timeout = 0 } };
            _ = &dmp;
            _ = try checkAllAllocationFailures(testing.allocator, testDiffLineMode, .{ (&dmp), "1234567890\n1234567890\n1234567890\n", "abcdefghij\nabcdefghij\nabcdefghij\n" });
    }
    test diffCleanupSemantic {
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{}), .expected = (&.{}) } });
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{ .{ .operation = .delete, .text = "ab" }, .{ .operation = .insert, .text = "cd" }, .{ .operation = .equal, .text = "12" }, .{ .operation = .delete, .text = "e" } }), .expected = (&.{ .{ .operation = .delete, .text = "ab" }, .{ .operation = .insert, .text = "cd" }, .{ .operation = .equal, .text = "12" }, .{ .operation = .delete, .text = "e" } }) } });
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{ .{ .operation = .delete, .text = "abc" }, .{ .operation = .insert, .text = "ABC" }, .{ .operation = .equal, .text = "1234" }, .{ .operation = .delete, .text = "wxyz" } }), .expected = (&.{ .{ .operation = .delete, .text = "abc" }, .{ .operation = .insert, .text = "ABC" }, .{ .operation = .equal, .text = "1234" }, .{ .operation = .delete, .text = "wxyz" } }) } });
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{ .{ .operation = .delete, .text = "a" }, .{ .operation = .equal, .text = "b" }, .{ .operation = .delete, .text = "c" } }), .expected = (&.{ .{ .operation = .delete, .text = "abc" }, .{ .operation = .insert, .text = "b" } }) } });
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{ .{ .operation = .delete, .text = "ab" }, .{ .operation = .equal, .text = "cd" }, .{ .operation = .delete, .text = "e" }, .{ .operation = .equal, .text = "f" }, .{ .operation = .insert, .text = "g" } }), .expected = (&.{ .{ .operation = .delete, .text = "abcdef" }, .{ .operation = .insert, .text = "cdfg" } }) } });
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{ .{ .operation = .insert, .text = "1" }, .{ .operation = .equal, .text = "A" }, .{ .operation = .delete, .text = "B" }, .{ .operation = .insert, .text = "2" }, .{ .operation = .equal, .text = "_" }, .{ .operation = .insert, .text = "1" }, .{ .operation = .equal, .text = "A" }, .{ .operation = .delete, .text = "B" }, .{ .operation = .insert, .text = "2" } }), .expected = (&.{ .{ .operation = .delete, .text = "AB_AB" }, .{ .operation = .insert, .text = "1A2_1A2" } }) } });
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{ .{ .operation = .equal, .text = "The c" }, .{ .operation = .delete, .text = "ow and the c" }, .{ .operation = .equal, .text = "at." } }), .expected = (&.{ .{ .operation = .equal, .text = "The " }, .{ .operation = .delete, .text = "cow and the " }, .{ .operation = .equal, .text = "cat." } }) } });
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{ .{ .operation = .delete, .text = "abcxx" }, .{ .operation = .insert, .text = "xxdef" } }), .expected = (&.{ .{ .operation = .delete, .text = "abcxx" }, .{ .operation = .insert, .text = "xxdef" } }) } });
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{ .{ .operation = .delete, .text = "abcxxx" }, .{ .operation = .insert, .text = "xxxdef" } }), .expected = (&.{ .{ .operation = .delete, .text = "abc" }, .{ .operation = .equal, .text = "xxx" }, .{ .operation = .insert, .text = "def" } }) } });
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{ .{ .operation = .delete, .text = "xxxabc" }, .{ .operation = .insert, .text = "defxxx" } }), .expected = (&.{ .{ .operation = .insert, .text = "def" }, .{ .operation = .equal, .text = "xxx" }, .{ .operation = .delete, .text = "abc" } }) } });
            _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupSemantic, .{ .{ .input = (&.{ .{ .operation = .delete, .text = "abcd1212" }, .{ .operation = .insert, .text = "1212efghi" }, .{ .operation = .equal, .text = "----" }, .{ .operation = .delete, .text = "A3" }, .{ .operation = .insert, .text = "3BC" } }), .expected = (&.{ .{ .operation = .delete, .text = "abcd" }, .{ .operation = .equal, .text = "1212" }, .{ .operation = .insert, .text = "efghi" }, .{ .operation = .equal, .text = "----" }, .{ .operation = .delete, .text = "A" }, .{ .operation = .equal, .text = "3" }, .{ .operation = .insert, .text = "BC" } }) } });
    }
    test "diffCleanupEfficiency" {
            const allocator = testing.allocator;
            var dmp: DiffMatchPatch = .default;
            _ = &dmp;
            dmp.config.diff_edit_cost = 4;
            {
                var diffs: DiffList = .empty;
                _ = &diffs;
                _ = try dmp.diffCleanupEfficiency(allocator, (&diffs));
                _ = try testing.expectEqualDeep(DiffList.empty, diffs);
            }
            {
                const dslice: []const Diff = (&.{ .{ .operation = .delete, .text = "ab" }, .{ .operation = .insert, .text = "12" }, .{ .operation = .equal, .text = "wxyz" }, .{ .operation = .delete, .text = "cd" }, .{ .operation = .insert, .text = "34" } });
                _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupEfficiency, .{ dmp, .{ .input = dslice, .expected = dslice } });
            }
            {
                const dslice: []const Diff = (&.{ .{ .operation = .delete, .text = "ab" }, .{ .operation = .insert, .text = "12" }, .{ .operation = .equal, .text = "xyz" }, .{ .operation = .delete, .text = "cd" }, .{ .operation = .insert, .text = "34" } });
                const d_after: []const Diff = (&.{ .{ .operation = .delete, .text = "abxyzcd" }, .{ .operation = .insert, .text = "12xyz34" } });
                _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupEfficiency, .{ dmp, .{ .input = dslice, .expected = d_after } });
            }
            {
                const dslice: []const Diff = (&.{ .{ .operation = .insert, .text = "12" }, .{ .operation = .equal, .text = "x" }, .{ .operation = .delete, .text = "cd" }, .{ .operation = .insert, .text = "34" } });
                const d_after: []const Diff = (&.{ .{ .operation = .delete, .text = "xcd" }, .{ .operation = .insert, .text = "12x34" } });
                _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupEfficiency, .{ dmp, .{ .input = dslice, .expected = d_after } });
            }
            {
                const dslice: []const Diff = (&.{ .{ .operation = .delete, .text = "ab" }, .{ .operation = .insert, .text = "12" }, .{ .operation = .equal, .text = "xy" }, .{ .operation = .insert, .text = "34" }, .{ .operation = .equal, .text = "z" }, .{ .operation = .delete, .text = "cd" }, .{ .operation = .insert, .text = "56" } });
                const d_after: []const Diff = (&.{ .{ .operation = .delete, .text = "abxyzcd" }, .{ .operation = .insert, .text = "12xy34z56" } });
                _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupEfficiency, .{ dmp, .{ .input = dslice, .expected = d_after } });
            }
            {
                dmp.config.diff_edit_cost = 5;
                const dslice: []const Diff = (&.{ .{ .operation = .delete, .text = "ab" }, .{ .operation = .insert, .text = "12" }, .{ .operation = .equal, .text = "wxyz" }, .{ .operation = .delete, .text = "cd" }, .{ .operation = .insert, .text = "34" } });
                const d_after: []const Diff = (&.{ .{ .operation = .delete, .text = "abwxyzcd" }, .{ .operation = .insert, .text = "12wxyz34" } });
                _ = try checkAllAllocationFailures(testing.allocator, testDiffCleanupEfficiency, .{ dmp, .{ .input = dslice, .expected = d_after } });
                dmp.config.diff_edit_cost = 4;
            }
    }
};
}
